    60→  private specToTasks = new Map<string, string[]>();
    61→
    62→  /** task ULID → spec ULID it references */
    63→  private taskToSpec = new Map<string, string>();
    64→
    65→  /** All spec items by ULID */
    66→  private specItems = new Map<string, LoadedSpecItem>();
    67→
    68→  /** All tasks by ULID */
    69→  private tasks = new Map<string, LoadedTask>();
    70→
    71→  /**
    72→   * Build index from loaded items
    73→   */
    74→  constructor(tasks: LoadedTask[], items: LoadedSpecItem[]) {
    75→    // Index spec items
    76→    for (const item of items) {
    77→      this.specItems.set(item._ulid, item);
    78→      this.specToTasks.set(item._ulid, []);
    79→    }
    80→
    81→    // Index tasks and build reverse mapping
    82→    for (const task of tasks) {
    83→      this.tasks.set(task._ulid, task);
    84→
    85→      if (task.spec_ref) {
    86→        // Store the raw ref - we'll resolve it when needed
    87→        this.taskToSpec.set(task._ulid, task.spec_ref);
    88→      }
    89→    }
    90→  }
    91→
    92→  /**
    93→   * Resolve task spec_refs and build the bidirectional index.
    94→   * Must be called with a ReferenceIndex to resolve @refs.
    95→   */
    96→  buildLinks(refIndex: ReferenceIndex): void {
    97→    for (const [taskUlid, specRef] of this.taskToSpec) {
    98→      const result = refIndex.resolve(specRef);
    99→      if (result.ok) {
   100→        const specUlid = result.ulid;
   101→        const existing = this.specToTasks.get(specUlid);
   102→        if (existing) {
   103→          existing.push(taskUlid);
   104→        }
   105→      }
   106→    }
   107→  }
   108→
   109→  /**
   110→   * Get tasks that implement a spec item
   111→   */
   112→  getTasksForSpec(specUlid: string): LoadedTask[] {
   113→    const taskUlids = this.specToTasks.get(specUlid) || [];
   114→    return taskUlids
   115→      .map((ulid) => this.tasks.get(ulid))
   116→      .filter((t): t is LoadedTask => t !== undefined);
   117→  }
   118→
   119→  /**
   120→   * Get the spec item a task implements
   121→   */
   122→  getSpecForTask(
   123→    taskUlid: string,
   124→    refIndex: ReferenceIndex,
   125→  ): LoadedSpecItem | undefined {
   126→    const specRef = this.taskToSpec.get(taskUlid);
   127→    if (!specRef) return undefined;
   128→
   129→    const result = refIndex.resolve(specRef);
   130→    if (result.ok) {
   131→      return this.specItems.get(result.ulid);
   132→    }
   133→    return undefined;
   134→  }
   135→
   136→  /**
   137→   * Calculate expected implementation status based on linked task statuses
   138→   */
   139→  calculateExpectedStatus(specUlid: string): ImplementationStatus {
   140→    const taskUlids = this.specToTasks.get(specUlid) || [];
   141→    if (taskUlids.length === 0) {
   142→      return "not_started";
   143→    }
   144→
   145→    const tasks = taskUlids
   146→      .map((ulid) => this.tasks.get(ulid))
   147→      .filter((t): t is LoadedTask => t !== undefined);
   148→
   149→    if (tasks.length === 0) {
   150→      return "not_started";
   151→    }
   152→
   153→    // Check task statuses
   154→    const hasInProgress = tasks.some((t) => t.status === "in_progress");
   155→    const allCompleted = tasks.every((t) => t.status === "completed");
   156→    const someCompleted = tasks.some((t) => t.status === "completed");
   157→
   158→    if (allCompleted) {
   159→      return "implemented";
   160→    }
   161→    if (hasInProgress || someCompleted) {
   162→      return "in_progress";
   163→    }
   164→    return "not_started";
   165→  }
   166→
   167→  /**
   168→   * Get implementation summary for a spec item
   169→   */
   170→  getImplementationSummary(
   171→    specUlid: string,
   172→  ): SpecImplementationSummary | undefined {
   173→    const spec = this.specItems.get(specUlid);
   174→    if (!spec) return undefined;
   175→
   176→    const taskUlids = this.specToTasks.get(specUlid) || [];
   177→    const linkedTasks: LinkedTaskSummary[] = taskUlids
   178→      .map((ulid) => this.tasks.get(ulid))
   179→      .filter((t): t is LoadedTask => t !== undefined)
   180→      .map((t) => ({
   181→        taskUlid: t._ulid,
   182→        taskTitle: t.title,
   183→        taskStatus: t.status,
   184→        hasNotes: t.notes.length > 0,
   185→      }));
   186→
   187→    const currentStatus = spec.status?.implementation || "not_started";
   188→    const expectedStatus = this.calculateExpectedStatus(specUlid);
   189→
   190→    return {
   191→      specUlid,
   192→      specTitle: spec.title,
   193→      currentStatus,
   194→      expectedStatus,
   195→      linkedTasks,
   196→      isAligned: currentStatus === expectedStatus,
   197→    };
   198→  }
   199→
   200→  /**
   201→   * Find all alignment issues
   202→   */
   203→  findAlignmentWarnings(): AlignmentWarning[] {
   204→    const warnings: AlignmentWarning[] = [];
   205→
   206→    // Check each spec item
   207→    for (const [specUlid, spec] of this.specItems) {
   208→      const taskUlids = this.specToTasks.get(specUlid) || [];
   209→      const currentStatus = spec.status?.implementation || "not_started";
   210→      const expectedStatus = this.calculateExpectedStatus(specUlid);
   211→
   212→      // Orphaned spec (no tasks)
   213→      // AC: @trait-retrospective ac-1
   214→      // Skip retrospective specs from orphaned warnings
   215→      // Policy: warn for not_started and in_progress (suspicious), but trust
   216→      // implemented/verified as baseline history predating the task system.
   217→      const isRetrospective = spec.traits?.includes("@trait-retrospective");
   218→      if (
   219→        taskUlids.length === 0 &&
   220→        (currentStatus === "not_started" || currentStatus === "in_progress") &&
   221→        !isRetrospective
   222→      ) {
   223→        warnings.push({
   224→          type: "orphaned_spec",
   225→          specUlid,
   226→          specTitle: spec.title,
   227→          message: `Spec item "${spec.title}" has no implementing tasks`,
   228→        });
   229→      }
   230→
   231→      // Status mismatch (only when tasks exist — no-task specs are handled above
   232→      // for not_started/in_progress; implemented/verified are trusted as baseline)
   233→      if (taskUlids.length > 0 && currentStatus !== expectedStatus) {
   234→        warnings.push({
   235→          type: "status_mismatch",
   236→          specUlid,
   237→          specTitle: spec.title,
   238→          message: `Spec "${spec.title}" status is "${currentStatus}" but should be "${expectedStatus}" based on task progress`,
   239→        });
   240→      }
   241→    }
   242→
   243→    // Check completed tasks with stale spec status
   244→    for (const [taskUlid, task] of this.tasks) {
   245→      if (task.status === "completed" && task.spec_ref) {
   246→        const specRef = this.taskToSpec.get(taskUlid);
   247→        if (specRef) {
   248→          // Note: We already checked this via spec iteration above
   249→          // But this provides task-centric context
   250→        }
   251→      }
   252→    }
   253→
   254→    return warnings;
   255→  }
   256→
   257→  /**
   258→   * Get all spec items with their implementation summary
   259→   */
   260→  getAllImplementationSummaries(): SpecImplementationSummary[] {
   261→    const summaries: SpecImplementationSummary[] = [];
   262→    for (const specUlid of this.specItems.keys()) {
   263→      const summary = this.getImplementationSummary(specUlid);
   264→      if (summary) {
   265→        summaries.push(summary);
   266→      }
   267→    }
   268→    return summaries;
   269→  }
   270→
   271→  /**
   272→   * Get stats about alignment
   273→   */
   274→  getStats(): {
   275→    totalSpecs: number;
   276→    specsWithTasks: number;
   277→    alignedSpecs: number;
   278→    orphanedSpecs: number;
   279→  } {
   280→    let specsWithTasks = 0;
   281→    let alignedSpecs = 0;
   282→    let orphanedSpecs = 0;
   283→
   284→    for (const specUlid of this.specItems.keys()) {
   285→      const taskUlids = this.specToTasks.get(specUlid) || [];
   286→      if (taskUlids.length > 0) {
   287→        specsWithTasks++;
   288→        const summary = this.getImplementationSummary(specUlid);
   289→        if (summary?.isAligned) {
   290→          alignedSpecs++;
   291→        }
   292→      } else {
   293→        orphanedSpecs++;
   294→      }
   295→    }
   296→
   297→    return {
   298→      totalSpecs: this.specItems.size,
   299→      specsWithTasks,
   300→      alignedSpecs,
   301→      orphanedSpecs,
   302→    };
   303→  }
   304→}
   305→
   306→// ============================================================
   307→// SYNC FUNCTIONS
   308→// ============================================================
   309→
   310→/**
   311→ * Result of syncing spec implementation status
   312→ */
   313→export interface SyncResult {
   314→  synced: boolean;
   315→  specUlid: string;
   316→  specTitle: string;
   317→  previousStatus: ImplementationStatus;
   318→  newStatus: ImplementationStatus;
   319→}
   320→
   321→/**
   322→ * Sync a spec item's implementation status based on its linked tasks.
   323→ * Called after task state changes (start, complete, etc.).
   324→ *
   325→ * @returns SyncResult if status changed, null if no change needed or no spec_ref
   326→ */
   327→export async function syncSpecImplementationStatus(
   328→  ctx: KspecContext,
   329→  task: LoadedTask,
   330→  allTasks: LoadedTask[],
   331→  allItems: LoadedSpecItem[],
   332→  refIndex: ReferenceIndex,
   333→): Promise<SyncResult | null> {
   334→  // Skip if task has no spec_ref
   335→  if (!task.spec_ref) {
   336→    return null;
   337→  }
   338→
   339→  // Resolve the spec reference
   340→  const result = refIndex.resolve(task.spec_ref);
   341→  if (!result.ok) {
   342→    return null;
   343→  }
   344→
   345→  // Find the spec item
   346→  const specItem = allItems.find((item) => item._ulid === result.ulid);
   347→  if (!specItem) {
   348→    return null;
   349→  }
   350→
   351→  // Build alignment index to calculate expected status
   352→  const alignmentIndex = new AlignmentIndex(allTasks, allItems);
   353→  alignmentIndex.buildLinks(refIndex);
   354→
   355→  const expectedStatus = alignmentIndex.calculateExpectedStatus(specItem._ulid);
   356→  const currentStatus = specItem.status?.implementation || "not_started";
   357→
   358→  // No change needed
   359→  if (currentStatus === expectedStatus) {
   360→    return null;
   361→  }
   362→
   363→  // Update the spec item
   364→  await updateSpecItem(ctx, specItem, {
   365→    status: {
   366→      maturity: specItem.status?.maturity || "draft",
   367→      implementation: expectedStatus,
   368→    },
   369→  });
   370→
   371→  return {
   372→    synced: true,
   373→    specUlid: specItem._ulid,
   374→    specTitle: specItem.title,
   375→    previousStatus: currentStatus,
   376→    newStatus: expectedStatus,
   377→  };
