/**
 * Validation module for kspec files.
 *
 * Provides schema validation, reference validation, and orphan detection.
 */

import * as fs from "node:fs/promises";
import * as path from "node:path";
import {
  AgentSchema,
  ConventionSchema,
  isSkill,
  ManifestSchema,
  MetaManifestSchema,
  ObservationSchema,
  SkillSchema,
  SpecItemSchema,
  TaskSchema,
  TasksFileSchema,
  UlidSchema,
  WorkflowSchema,
} from "../schema/index.js";
import { findMetaManifest, getSkillContentPath, loadMetaContext, type LoadedSkill } from "./meta.js";
import { loadPlans } from "./plans.js";
import {
  ReferenceIndex,
  type RefValidationError,
  type RefValidationWarning,
  shortestUniqueUlid,
  validateRefs,
} from "./refs.js";
import { TraitIndex } from "./traits.js";
import type { KspecContext, LoadedSpecItem, LoadedTask } from "./yaml.js";
