  loadSpecFile,
  readYamlFile,
} from "./yaml.js";

// ============================================================
// TYPES
// ============================================================

/**
 * Schema validation error
 */
export interface SchemaValidationError {
  file: string;
  path?: string;
  message: string;
  details?: unknown;
}

/**
 * Orphan item (not referenced by anything)
 */
export interface OrphanItem {
  ulid: string;
  title: string;
  type: string;
  file?: string;
}

/**
 * Completeness warning types
 */
export type CompletenessWarningType =
  | "missing_acceptance_criteria"
  | "missing_description"
  | "status_inconsistency"
  | "missing_test_coverage"
  | "automation_eligible_no_spec"
  | "ac_schema_field_mismatch";

/**
 * Trait cycle error
 */
export interface TraitCycleError {
  traitRef: string;
  traitTitle: string;
  cycle: string[];
  message: string;
}

/**
 * Completeness warning
 */
export interface CompletenessWarning {
  type: CompletenessWarningType;
  subtype?: "own_ac" | "trait_ac";
  itemRef: string;
  itemTitle: string;
  message: string;
  details?: string;
}

