import { z } from "zod";

// Common types used across spec and task schemas

/**
 * ULID pattern - 26 character Crockford base32
 * Excludes I, L, O, U to avoid confusion with 1, 1, 0, V
 */
export const ulidPattern = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/**
 * Slug pattern - lowercase alphanumeric with hyphens
 */
export const slugPattern = /^[a-z][a-z0-9-]*$/;

/**
 * Reference pattern - @ prefix followed by slug or ULID (or short ULID)
 */
export const refPattern = /^@[a-zA-Z0-9-]+$/;

// Base schemas
export const UlidSchema = z.string().regex(ulidPattern, "Invalid ULID format");
export const SlugSchema = z.string().regex(slugPattern, "Invalid slug format");
export const RefSchema = z
  .string()
  .regex(refPattern, "Invalid reference format");

// Priority can be string or number
export const PrioritySchema = z.union([
  z.enum(["high", "medium", "low"]),
  z.number().int().min(1).max(5),
]);

// ISO 8601 date or datetime
export const DateTimeSchema = z.union([
  z.string().datetime(),
  z.string().date(),
]);

// Maturity status
export const MaturitySchema = z.enum([
  "draft",
  "proposed",
  "stable",
  "deferred",
  "deprecated",
]);

// Implementation status
export const ImplementationStatusSchema = z.enum([
  "not_started",
  "in_progress",
  "implemented",
  "verified",
]);

// Task status
export const TaskStatusSchema = z.enum([
  "pending",
  "in_progress",
  "pending_review",
  "needs_work",
  "blocked",
  "completed",
  "cancelled",
]);

// Task type
export const TaskTypeSchema = z.enum(["epic", "task", "bug", "spike", "infra"]);

// Item type
export const ItemTypeSchema = z.enum([
  "module",
  "feature",
  "requirement",
  "constraint",
  "decision",
  "task",
  "trait",
]);

// VCS reference
export const VcsRefSchema = z.object({
  ref: z.string(),
  type: z.enum(["branch", "tag", "commit"]).optional(),
});

export type Ulid = z.infer<typeof UlidSchema>;
export type Slug = z.infer<typeof SlugSchema>;
export type Ref = z.infer<typeof RefSchema>;
export type Priority = z.infer<typeof PrioritySchema>;
export type DateTime = z.infer<typeof DateTimeSchema>;
export type Maturity = z.infer<typeof MaturitySchema>;
export type ImplementationStatus = z.infer<typeof ImplementationStatusSchema>;
export type TaskStatus = z.infer<typeof TaskStatusSchema>;
export type TaskType = z.infer<typeof TaskTypeSchema>;
export type ItemType = z.infer<typeof ItemTypeSchema>;
export type VcsRef = z.infer<typeof VcsRefSchema>;

/**
 * Normalize a reference string to ensure @ prefix.
 * Apply at CLI input boundaries before constructing TaskInput/SpecItemInput.
 * Prevents bare refs from failing RefSchema validation and causing silent data loss.
 */
export function normalizeRefInput(ref: string): string {
  return ref.startsWith("@") ? ref : `@${ref}`;
}

/**
 * Calculate expected implementation status based on linked task statuses
 */
calculateExpectedStatus(specUlid: string): ImplementationStatus {
  const taskUlids = this.specToTasks.get(specUlid) || [];
  if (taskUlids.length === 0) {
    return "not_started";
  }

  const tasks = taskUlids
    .map((ulid) => this.tasks.get(ulid))
    .filter((t): t is LoadedTask => t !== undefined);

  if (tasks.length === 0) {
    return "not_started";
  }

  // Check task statuses
  const hasInProgress = tasks.some((t) => t.status === "in_progress");
  const allCompleted = tasks.every((t) => t.status === "completed");
  const someCompleted = tasks.some((t) => t.status === "completed");

  if (allCompleted) {
    return "implemented";
  }
  if (hasInProgress || someCompleted) {
    return "in_progress";
  }
  return "not_started";
}

/**
 * Get implementation summary for a spec item
 */
getImplementationSummary(
  specUlid: string,
): SpecImplementationSummary | undefined {
  const spec = this.specItems.get(specUlid);
  if (!spec) return undefined;

  const taskUlids = this.specToTasks.get(specUlid) || [];
  const linkedTasks: LinkedTaskSummary[] = taskUlids
    .map((ulid) => this.tasks.get(ulid))
    .filter((t): t is LoadedTask => t !== undefined)
    .map((t) => ({
      taskUlid: t._ulid,
      taskTitle: t.title,
      taskStatus: t.status,
      hasNotes: t.notes.length > 0,
    }));

  const currentStatus = spec.status?.implementation || "not_started";
  const expectedStatus = this.calculateExpectedStatus(specUlid);

  return {
    specUlid,
    specTitle: spec.title,
    currentStatus,
    expectedStatus,
    linkedTasks,
    isAligned: currentStatus === expectedStatus,
  };
}

